import{_ as a,o as i,c as s,a6 as t}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"Type System Enhancements","description":"","frontmatter":{},"headers":[],"relativePath":"design/gap-type-system-enhancements.md","filePath":"design/gap-type-system-enhancements.md","lastUpdated":1781738315000}'),n={name:"design/gap-type-system-enhancements.md"};function l(r,e,o,p,c,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="type-system-enhancements" tabindex="-1">Type System Enhancements <a class="header-anchor" href="#type-system-enhancements" aria-label="Permalink to “Type System Enhancements”">​</a></h1><blockquote><p><strong>Status:</strong> Restructured from 4-feature monolith into 4 independent sub-proposals. Each sub-proposal is independently estimable and deliverable.</p></blockquote><hr><h2 id="sub-proposal-a-never-type-2-weeks" tabindex="-1">Sub-Proposal A: <code>never</code> Type (2 weeks) <a class="header-anchor" href="#sub-proposal-a-never-type-2-weeks" aria-label="Permalink to “Sub-Proposal A: never Type (2 weeks)”">​</a></h2><h3 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h3><p>Add a bottom type <code>never</code> that represents computations that never produce a value.</p><h3 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h3><p>Currently, functions like <code>exit(1)</code>, <code>panic()</code>, or infinite loops cannot be used as expressions. The type checker must reject valid patterns:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun unwrapOrPanic&lt;T&gt;(opt: Option&lt;T&gt;) -&gt; T {</span></span>
<span class="line"><span>    match (opt) {</span></span>
<span class="line"><span>        case Some(v) =&gt; v;</span></span>
<span class="line"><span>        case None =&gt; exit(1);  // ERROR: exit returns unit, not T</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h3><h4 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to “Syntax”">​</a></h4><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun exit(code: i32) -&gt; never;   // Function never returns</span></span></code></pre></div><p><code>never</code> is a built-in type, like <code>unit</code>.</p><h4 id="type-checking-rules" tabindex="-1">Type Checking Rules <a class="header-anchor" href="#type-checking-rules" aria-label="Permalink to “Type Checking Rules”">​</a></h4><ol><li><code>never</code> unifies with <strong>any</strong> type (it&#39;s a bottom type)</li><li>A function declared <code>-&gt; never</code> never returns normally</li><li>The type of <code>return</code> in a <code>never</code>-returning function is <code>never</code></li><li><code>never</code> cannot be assigned to a variable of type <code>never</code> (no values of type <code>never</code> exist)</li><li>The result type of a <code>loop { break; }</code> or <code>match</code> with all branches returning <code>never</code> is <code>never</code></li></ol><h4 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h4><p>The <code>never</code> type is added to the type system as a new <code>PrimitiveType</code> variant:</p><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// In include/typecheck/typeinfo.hpp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NeverType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : TypeInfo {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Singleton: no fields</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><h4 id="grammar-changes" tabindex="-1">Grammar Changes <a class="header-anchor" href="#grammar-changes" aria-label="Permalink to “Grammar Changes”">​</a></h4><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Token: KEYWORD_NEVER (already exists as part of the language? Check.)</span></span>
<span class="line"><span>// If not: add to lexer, map to builtin type.</span></span>
<span class="line"><span>fun abort() -&gt; never = native;</span></span></code></pre></div><h3 id="sub-proposal-a-acceptance-criteria" tabindex="-1">Sub-Proposal A Acceptance Criteria <a class="header-anchor" href="#sub-proposal-a-acceptance-criteria" aria-label="Permalink to “Sub-Proposal A Acceptance Criteria”">​</a></h3><ul><li><code>fun exit() -&gt; never</code> compiles and the type checker accepts it</li><li><code>match (opt) { case Some(v) =&gt; v; case None =&gt; exit(); }</code> type-checks (never unifies with T)</li><li>A value of type <code>never</code> cannot be created (compile error)</li><li><code>never</code> can be used in return position of native functions</li><li>All existing tests pass</li></ul><hr><h2 id="sub-proposal-b-impl-trait-3-weeks" tabindex="-1">Sub-Proposal B: <code>impl Trait</code> (3 weeks) <a class="header-anchor" href="#sub-proposal-b-impl-trait-3-weeks" aria-label="Permalink to “Sub-Proposal B: impl Trait (3 weeks)”">​</a></h2><h3 id="goal-1" tabindex="-1">Goal <a class="header-anchor" href="#goal-1" aria-label="Permalink to “Goal”">​</a></h3><p>Allow functions to return opaque types that implement a trait, without naming the concrete type.</p><h3 id="motivation-1" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-1" aria-label="Permalink to “Motivation”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Without impl Trait: must name the concrete iterator type</span></span>
<span class="line"><span>fun range(start: i32, end: i32) -&gt; RangeIter&lt;i32&gt; { ... }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// With impl Trait: return any type implementing Iterator</span></span>
<span class="line"><span>fun range(start: i32, end: i32) -&gt; impl Iterator&lt;Item = i32&gt; { ... }</span></span></code></pre></div><h3 id="design-1" tabindex="-1">Design <a class="header-anchor" href="#design-1" aria-label="Permalink to “Design”">​</a></h3><h4 id="syntax-1" tabindex="-1">Syntax <a class="header-anchor" href="#syntax-1" aria-label="Permalink to “Syntax”">​</a></h4><p>Return position:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun makeIterator() -&gt; impl Iterator&lt;Item = i32&gt; {</span></span>
<span class="line"><span>    return RangeIter&lt;i32&gt; { start: 0, end: 10 };</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Argument position:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun process(items: impl Iterable) {</span></span>
<span class="line"><span>    for item in items { ... }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="type-checking" tabindex="-1">Type Checking <a class="header-anchor" href="#type-checking" aria-label="Permalink to “Type Checking”">​</a></h4><ul><li><code>impl Trait</code> in return position creates an <strong>existential type</strong>: &quot;there exists some type T such that T: Trait&quot;</li><li>The concrete type is inferred from the function body</li><li>The caller cannot name or depend on the concrete type</li><li><code>impl Trait</code> in argument position is syntactic sugar for a generic parameter: <code>fun process&lt;T: Iterable&gt;(items: T)</code></li></ul><h4 id="implementation-1" tabindex="-1">Implementation <a class="header-anchor" href="#implementation-1" aria-label="Permalink to “Implementation”">​</a></h4><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ImplTraitType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : TypeInfo {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CheckingRef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TraitBound</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bound;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // The trait constraint</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>The type checker:</p><ol><li>Creates an <code>ImplTraitType</code> as the return type</li><li>Checks that the returned expression satisfies the trait bound</li><li>When used by the caller, only the trait methods are visible</li></ol><h3 id="sub-proposal-b-acceptance-criteria" tabindex="-1">Sub-Proposal B Acceptance Criteria <a class="header-anchor" href="#sub-proposal-b-acceptance-criteria" aria-label="Permalink to “Sub-Proposal B Acceptance Criteria”">​</a></h3><ul><li><code>fun foo() -&gt; impl Show { ... }</code> compiles and the returned value can call <code>.show()</code></li><li>A different return type that still impl <code>Show</code> is accepted</li><li>A return type that does NOT impl <code>Show</code> is a compile error</li><li><code>impl Trait</code> in argument position accepts any matching concrete type</li><li>Multiple calls to the same function with different concrete types both work</li></ul><hr><h2 id="sub-proposal-c-compile-time-borrow-checker-3-4-months" tabindex="-1">Sub-Proposal C: Compile-Time Borrow Checker (3-4 months) <a class="header-anchor" href="#sub-proposal-c-compile-time-borrow-checker-3-4-months" aria-label="Permalink to “Sub-Proposal C: Compile-Time Borrow Checker (3-4 months)”">​</a></h2><h3 id="goal-2" tabindex="-1">Goal <a class="header-anchor" href="#goal-2" aria-label="Permalink to “Goal”">​</a></h3><p>Replace the current <strong>runtime</strong> use-after-move detection with <strong>compile-time</strong> ownership and borrowing rules.</p><h3 id="motivation-2" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-2" aria-label="Permalink to “Motivation”">​</a></h3><p>Currently, use-after-move is checked at runtime:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = [1, 2, 3];</span></span>
<span class="line"><span>val y = move x;</span></span>
<span class="line"><span>print(x[0]);  // Runtime error: use after move</span></span></code></pre></div><p>A compile-time borrow checker would catch this before execution, providing stronger safety guarantees and eliminating the runtime error path.</p><h3 id="design-2" tabindex="-1">Design <a class="header-anchor" href="#design-2" aria-label="Permalink to “Design”">​</a></h3><h4 id="borrowing-rules-phase-1-lexical-borrows" tabindex="-1">Borrowing Rules (Phase 1: Lexical Borrows) <a class="header-anchor" href="#borrowing-rules-phase-1-lexical-borrows" aria-label="Permalink to “Borrowing Rules (Phase 1: Lexical Borrows)”">​</a></h4><p>The type checker enforces:</p><ol><li><strong>At any time, a value has either</strong>: <ul><li>One <code>ref&lt;T&gt;</code> (mutable reference), OR</li><li>Any number of <code>ref&lt;const T&gt;</code> (immutable references)</li></ul></li><li><strong>A reference must not outlive its referent</strong> (lexical scope check)</li><li><strong>A value cannot be used after <code>move</code></strong> (already partially implemented)</li><li><strong>A moved field cannot be accessed until reassigned</strong> (already implemented as partial move tracking)</li></ol><h4 id="type-checker-implementation" tabindex="-1">Type Checker Implementation <a class="header-anchor" href="#type-checker-implementation" aria-label="Permalink to “Type Checker Implementation”">​</a></h4><p>The existing partial move tracking in <code>typecheck.cpp</code> is extended:</p><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// New tracking structures</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BorrowEntry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Str place;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            // e.g., &quot;person.name&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RefKind kind;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // Mutable | Immutable</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SourcePosition start;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // Where the borrow started</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SourcePosition end;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // Where the borrow ends (scope exit)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MoveTracker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    HashMap</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Str, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> moved;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       // place → isMoved</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Vec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BorrowEntry</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> activeBorrows;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // currently active borrows</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><h4 id="migration-path" tabindex="-1">Migration Path <a class="header-anchor" href="#migration-path" aria-label="Permalink to “Migration Path”">​</a></h4><ol><li><strong>Phase 1a</strong>: Add compile-time warnings for move/borrow violations (during type checking)</li><li><strong>Phase 1b</strong>: Convert warnings to errors for simple cases (lexical borrows only)</li><li><strong>Phase 1c</strong>: Keep runtime check as fallback for complex cases not yet handled</li></ol><h4 id="code-changes" tabindex="-1">Code Changes <a class="header-anchor" href="#code-changes" aria-label="Permalink to “Code Changes”">​</a></h4><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>src/typecheck/typecheck.cpp</code></td><td>Add borrow tracking alongside existing move tracking</td></tr><tr><td><code>src/typecheck/typecheck.cpp</code></td><td><code>visit(RefExpression*)</code> → register borrow scope</td></tr><tr><td><code>src/typecheck/typecheck.cpp</code></td><td><code>visit(AssignmentExpression*)</code> → check borrow conflicts</td></tr><tr><td><code>src/typecheck/typecheck.cpp</code></td><td><code>visit(IdExpression*)</code> → check use-after-move</td></tr><tr><td><code>src/runtime/</code></td><td>Keep runtime checks in debug mode; skip in release</td></tr></tbody></table><h3 id="sub-proposal-c-acceptance-criteria" tabindex="-1">Sub-Proposal C Acceptance Criteria <a class="header-anchor" href="#sub-proposal-c-acceptance-criteria" aria-label="Permalink to “Sub-Proposal C Acceptance Criteria”">​</a></h3><ul><li><code>val y = move x; print(x[0]);</code> is a <strong>compile-time warning</strong> (not runtime error — Phase 1 keeps runtime check)</li><li>Two simultaneous <code>ref&lt;T&gt;</code> to the same value is a compile error</li><li><code>ref&lt;T&gt;</code> and <code>ref&lt;const T&gt;</code> cannot coexist</li><li>A reference doesn&#39;t outlive its referent (lexical scope) — compile-time warning</li><li>Partial moves are compile-time warnings on subsequent reads</li><li>Runtime use-after-move check is always present as a safety net</li><li>All existing tests pass unchanged</li></ul><h3 id="scope-limit-lexical-borrows-only" tabindex="-1">Scope Limit: Lexical Borrows Only <a class="header-anchor" href="#scope-limit-lexical-borrows-only" aria-label="Permalink to “Scope Limit: Lexical Borrows Only”">​</a></h3><p>This implementation limits itself to <strong>lexical borrows</strong> (reference scope = enclosing block). It does NOT attempt:</p><ul><li>Non-lexical lifetimes (NLL) — would require flow-sensitive analysis</li><li>Two-phase borrows — future enhancement</li><li>Lifetime elision — future enhancement</li></ul><p>The existing runtime move checking remains as a safety net for any cases the compile-time checker cannot prove.</p><hr><h2 id="sub-proposal-d-generic-associated-types-gat-—-4-6-months" tabindex="-1">Sub-Proposal D: Generic Associated Types (GAT) — 4-6 months <a class="header-anchor" href="#sub-proposal-d-generic-associated-types-gat-—-4-6-months" aria-label="Permalink to “Sub-Proposal D: Generic Associated Types (GAT) — 4-6 months”">​</a></h2><h3 id="goal-3" tabindex="-1">Goal <a class="header-anchor" href="#goal-3" aria-label="Permalink to “Goal”">​</a></h3><p>Allow traits to have associated types that are themselves generic over lifetimes or type parameters.</p><h3 id="motivation-3" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-3" aria-label="Permalink to “Motivation”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trait Collection {</span></span>
<span class="line"><span>    type Item;</span></span>
<span class="line"><span>    type Iter&lt;&#39;a&gt;: Iterator where Self: &#39;a;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fun iter&lt;&#39;a&gt;(self: ref&lt;&#39;a, Self&gt;) -&gt; Self::Iter&lt;&#39;a&gt;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>impl Collection for [i32] {</span></span>
<span class="line"><span>    type Item = i32;</span></span>
<span class="line"><span>    type Iter&lt;&#39;a&gt; = SliceIter&lt;&#39;a, i32&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fun iter&lt;&#39;a&gt;(self: ref&lt;&#39;a, Self&gt;) -&gt; SliceIter&lt;&#39;a, i32&gt; { ... }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="design-3" tabindex="-1">Design <a class="header-anchor" href="#design-3" aria-label="Permalink to “Design”">​</a></h3><h4 id="syntax-2" tabindex="-1">Syntax <a class="header-anchor" href="#syntax-2" aria-label="Permalink to “Syntax”">​</a></h4><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trait StreamingIterator {</span></span>
<span class="line"><span>    type Item&lt;&#39;a&gt;: SomeTrait;</span></span>
<span class="line"><span>    fun next&lt;&#39;a&gt;(self: ref&lt;&#39;a, Self&gt;) -&gt; Option&lt;Self::Item&lt;&#39;a&gt;&gt;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="type-checker-implementation-1" tabindex="-1">Type Checker Implementation <a class="header-anchor" href="#type-checker-implementation-1" aria-label="Permalink to “Type Checker Implementation”">​</a></h4><p>GATs require:</p><ol><li><strong>GAT declaration syntax</strong> in trait definitions</li><li><strong>GAT implementation</strong> in impl blocks</li><li><strong>GAT resolution</strong> when <code>Self::Item&lt;&#39;a&gt;</code> is used</li><li><strong>Where clause support</strong> for GAT bounds</li></ol><p>GATs are fundamentally higher-kinded: <code>Item</code> is a type constructor <code>Lifetime → Type</code>. The existing HKT infrastructure (<code>F&lt;_&gt;</code>) can be extended to support lifetime parameters.</p><h4 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h4><ul><li>Requires existing HKT infrastructure (already implemented)</li><li>Requires lifetime parameter support in the type system (new)</li></ul><h3 id="sub-proposal-d-acceptance-criteria" tabindex="-1">Sub-Proposal D Acceptance Criteria <a class="header-anchor" href="#sub-proposal-d-acceptance-criteria" aria-label="Permalink to “Sub-Proposal D Acceptance Criteria”">​</a></h3><ul><li>A trait with a GAT compiles</li><li>An impl provides a concrete GAT mapping</li><li><code>Self::Item&lt;&#39;a&gt;</code> resolves to the correct type</li><li>GATs work with where clauses: <code>where &lt;T as Collection&gt;::Iter&lt;&#39;a&gt;: Iterator</code></li><li>Complex examples (e.g., streaming iterator) compile and type-check correctly</li></ul><hr><h2 id="gat-feasibility-note" tabindex="-1">GAT Feasibility Note <a class="header-anchor" href="#gat-feasibility-note" aria-label="Permalink to “GAT Feasibility Note”">​</a></h2><p><strong>Verdict: Not achievable without a lifetime system.</strong> GATs require:</p><ul><li>Lifetime parameter syntax in trait declarations</li><li>Lifetime inference and variance checking</li><li>Lifetime-aware type unification</li></ul><p>None of these exist in NG, and adding a lifetime system is a 12+ month project on its own.</p><p><strong>Recommendation:</strong> Defer indefinitely. Revisit when/if NG gains lifetime annotations.</p><hr><h2 id="summary-implementation-order" tabindex="-1">Summary: Implementation Order <a class="header-anchor" href="#summary-implementation-order" aria-label="Permalink to “Summary: Implementation Order”">​</a></h2><table tabindex="0"><thead><tr><th>Order</th><th>Feature</th><th>Effort</th><th>Dependencies</th><th>Risk</th></tr></thead><tbody><tr><td>1</td><td><code>never</code> type</td><td>2 weeks</td><td>None</td><td>🟢 Low</td></tr><tr><td>2</td><td><code>impl Trait</code></td><td>3 weeks</td><td>Trait system (exists)</td><td>🟡 Medium</td></tr><tr><td>3</td><td>Borrow checker (lexical only)</td><td>6-8 weeks</td><td>Partial move tracking (exists)</td><td>🟡 Medium</td></tr><tr><td>4</td><td>GAT</td><td><strong>Deferred indefinitely</strong></td><td>Needs lifetime system</td><td>🔴 Very High</td></tr></tbody></table>`,93)])])}const k=a(n,[["render",l]]);export{g as __pageData,k as default};
